import{_ as n,C as i,o as l,c as h,j as e,a as d,E as o,aj as a}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"Timeline","description":"","frontmatter":{},"headers":[],"relativePath":"components/timeline.md","filePath":"components/timeline.md","lastUpdated":1789206102000}'),s={name:"components/timeline.md"},m={id:"timeline",tabindex:"-1"};function b(p,t,u,f,x,g){const r=i("Badge"),c=i("XhDemo");return l(),h("div",null,[e("h1",m,[t[0]||(t[0]=d("Timeline ",-1)),o(r,{type:"info",text:"时间线"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#timeline","aria-label":'Permalink to "Timeline <Badge type="info" text="时间线" />"'},"​",-1))]),t[3]||(t[3]=a('<p>按时间顺序排开的一串事件，每条有标记、连接线与内容。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/timeline" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/timeline.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/timeline" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/timeline" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/timeline.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一条竖向的事件流：每条一个圆点，圆点之间连一截线，末条的线自动收掉</p>',4)),o(c,{src:"timeline/01-basic"}),t[4]||(t[4]=e("h2",{id:"示例",tabindex:"-1"},[d("示例 "),e("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=e("h3",{id:"逐条语气",tabindex:"-1"},[d("逐条语气 "),e("a",{class:"header-anchor",href:"#逐条语气","aria-label":'Permalink to "逐条语气"'},"​")],-1)),t[6]||(t[6]=e("p",null,"tone 写在条目上，只给这一条的圆点上色；不写 tone 的条目是中性圆点",-1)),o(c,{src:"timeline/02-tone"}),t[7]||(t[7]=e("h3",{id:"内容在哪一侧",tabindex:"-1"},[d("内容在哪一侧 "),e("a",{class:"header-anchor",href:"#内容在哪一侧","aria-label":'Permalink to "内容在哪一侧"'},"​")],-1)),t[8]||(t[8]=e("p",null,"placement 决定内容落在线的哪一侧；alternate 是逐条交替，线走中间",-1)),o(c,{src:"timeline/03-placement"}),t[9]||(t[9]=e("h3",{id:"横排",tabindex:"-1"},[d("横排 "),e("a",{class:"header-anchor",href:"#横排","aria-label":'Permalink to "横排"'},"​")],-1)),t[10]||(t[10]=e("p",null,'orientation="horizontal" 把事件从左往右摆，连线随之转成横的一条',-1)),o(c,{src:"timeline/04-horizontal"}),t[11]||(t[11]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[12]||(t[12]=e("p",null,"size 换的是圆点直径、条目间距与字号，不传 size 即默认档",-1)),o(c,{src:"timeline/05-size"}),t[13]||(t[13]=e("h3",{id:"坐标列",tabindex:"-1"},[d("坐标列 "),e("a",{class:"header-anchor",href:"#坐标列","aria-label":'Permalink to "坐标列"'},"​")],-1)),t[14]||(t[14]=e("p",null,"label 与内容对置：逐条交替排布时时间戳仍停在同一侧，不跟着内容左右横跳",-1)),o(c,{src:"timeline/06-label"}),t[15]||(t[15]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>展示已经发生的事件序列：审批记录、物流轨迹、变更历史。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>表达&quot;还要走几步&quot;：用<a href="./steps">步骤条</a>——时间线是回顾，步骤条是前瞻。</li><li>事件之间没有时间关系：用<a href="./list">列表</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>逐条可以有自己的语气（成功 / 失败 / 进行中）。</li><li>内容可以固定在一侧，也可以左右交替。</li><li>支持横排。</li><li><code>label</code> 是与内容对置的那一列，装这一条的坐标（日期、版本号）；逐条交替排布时时间戳因此不跟着内容左右横跳。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-timeline&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTimelineConnector</code> <code>XhTimelineContent</code> <code>XhTimelineDescription</code> <code>XhTimelineIndicator</code> <code>XhTimelineItem</code> <code>XhTimelineLabel</code> <code>XhTimelineRoot</code> <code>XhTimelineTime</code> <code>XhTimelineTitle</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/timeline.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;timeline&quot;</code>：<strong><code>root</code></strong> · <strong><code>item</code></strong> · <code>label</code> · <code>indicator</code> · <code>connector</code> · <code>content</code> · <code>title</code> · <code>description</code> · <code>time</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>事件排列方向：vertical 自上而下、horizontal 自起点向终点，缺省 vertical。</td></tr><tr><td><code>placement</code></td><td><code>TimelinePlacement</code></td><td></td><td>内容在线的哪一侧：start / end / alternate，不写则内容落在结束侧。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定圆点直径、条目间距与字号。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>与内容对置的那一列，装这一条的坐标；排布随整条线的方向与侧别走。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: TimelineItemProps) =&gt; T[&#39;element&#39;]</code></td><td>圆点的语气取自它所属的条目。</td></tr><tr><td><code>getConnectorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTimeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;list&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;listitem&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>connector</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/timeline.css</code> 按部件选择：<code>[data-scope=&quot;timeline&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>item</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>label</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>label</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>indicator</code></td><td><code>data-tone</code></td><td>item.tone</td></tr><tr><td><code>connector</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-timeline-connector-bg</code></td><td><code>connector</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>timeline 的 connector 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timeline-connector-min-length</code></td><td><code>connector</code><br><code>item</code><br><code>label</code></td><td><code>min-block-size</code><br><code>min-inline-size</code></td><td><code>@media (min-width: 768px)</code><br><code>default</code><br><code>has(&gt; [data-scope=&#39;timeline&#39;][data-part=&#39;label&#39;])</code><br><code>orientation=horizontal</code></td><td><code>--xh-space-4</code></td><td>timeline 的 connector、item、label 部件 min-block-size、min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-connector-radius</code></td><td><code>connector</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>timeline 的 connector 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-timeline-connector-thickness</code></td><td><code>connector</code><br><code>item</code><br><code>label</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>@media (min-width: 768px)</code><br><code>default</code><br><code>has(&gt; [data-scope=&#39;timeline&#39;][data-part=&#39;label&#39;])</code><br><code>orientation=horizontal</code></td><td><code>--xh-stroke-thick</code></td><td>timeline 的 connector、item、label 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-content-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>timeline 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-timeline-content-pb</code></td><td><code>content</code><br><code>item</code></td><td><code>padding-block-end</code></td><td><code>@media (min-width: 768px)</code><br><code>nth-child(even)</code><br><code>orientation=horizontal</code><br><code>placement=alternate</code><br><code>placement=start</code></td><td><code>--xh-space-2</code></td><td>timeline 的 content、item 部件 padding-block-end 覆盖槽。</td></tr><tr><td><code>--xh-timeline-content-pt</code></td><td><code>content</code><br><code>item</code><br><code>label</code></td><td><code>padding-block-start</code></td><td><code>@media (min-width: 768px)</code><br><code>has(&gt; [data-scope=&#39;timeline&#39;][data-part=&#39;label&#39;])</code><br><code>orientation=horizontal</code></td><td><code>--xh-space-2</code></td><td>timeline 的 content、item、label 部件 padding-block-start 覆盖槽。</td></tr><tr><td><code>--xh-timeline-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>timeline 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-body-size</code></td><td>timeline 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timeline 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-gutter</code></td><td><code>item</code></td><td><code>column-gap</code></td><td><code>default</code></td><td><code>--xh-_timeline-gutter</code></td><td>timeline 的 item 部件 column-gap 覆盖槽。</td></tr><tr><td><code>--xh-timeline-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tone-soft</code></td><td>timeline 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timeline-indicator-fg</code></td><td><code>indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-on</code></td><td>timeline 的 indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-indicator-font-size</code></td><td><code>indicator</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_timeline-caption-font-size</code></td><td>timeline 的 indicator 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-indicator-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>timeline 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-timeline-indicator-size</code></td><td><code>indicator</code><br><code>item</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>margin-block-start</code></td><td><code>default</code></td><td><code>--xh-_timeline-dot-size</code></td><td>timeline 的 indicator、item 部件 block-size、inline-size、margin-block-start 覆盖槽。</td></tr><tr><td><code>--xh-timeline-item-gap</code></td><td><code>content</code><br><code>item</code><br><code>label</code></td><td><code>padding-block-end</code><br><code>padding-inline-end</code></td><td><code>@media (min-width: 768px)</code><br><code>default</code><br><code>has(&gt; [data-scope=&#39;timeline&#39;][data-part=&#39;label&#39;])</code><br><code>orientation=horizontal</code></td><td><code>--xh-_timeline-item-gap</code></td><td>timeline 的 content、item、label 部件 padding-block-end、padding-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-timeline-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>timeline 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_timeline-caption-font-size</code></td><td>timeline 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-time-fg</code></td><td><code>time</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>timeline 的 time 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-time-font-size</code></td><td><code>time</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_timeline-caption-font-size</code></td><td>timeline 的 time 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timeline-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timeline 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timeline-title-font-size</code></td><td><code>indicator</code><br><code>item</code><br><code>root</code><br><code>title</code></td><td><code>font-size</code><br><code>margin-block-start</code></td><td><code>default</code></td><td><code>--xh-_timeline-title-font-size</code></td><td>timeline 的 indicator、item、root、title 部件 font-size、margin-block-start 覆盖槽。</td></tr><tr><td><code>--xh-timeline-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>timeline 的 title 部件 font-weight 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤按视口分档：<code>min-width: 768px</code>。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>时间位放<a href="./timestamp">时间戳</a>；内容里放<a href="./card">卡片</a>或<a href="./descriptions">描述列表</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>顺序保持一致：要么恒为最新在上，要么恒为最早在上，别混。</li><li>每条都写清楚时刻，只写&quot;刚刚&quot;在回溯时没有价值。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>条数很多却不折叠：一条时间线拉出十屏。</li><li>用颜色区分事件类型却不给文字。</li></ul>',44))])}const P=n(s,[["render",b]]);export{q as __pageData,P as default};
